import requests
from requests.models import PreparedRequest
from collections.abc import Iterable

class ProxyIterable:
    def __init__(self, iterable):
        self._iterable = iterable

    def __getattr__(self, name):
        return getattr(self._iterable, name)

    def __iter__(self):
        return iter(self._iterable)

def test_proxy_iterable():
    data = ProxyIterable([b"1", b"2", b"3"])

    # Check if it's an Iterable
    print(f"isinstance(data, Iterable): {isinstance(data, Iterable)}")
    print(f"hasattr(data, '__iter__'): {hasattr(data, '__iter__')}")

    req = PreparedRequest()
    req.prepare_body(data=data, files=None)

    print(f"req.headers: {req.headers}")
    if "Transfer-Encoding" in req.headers or "Content-Length" in req.headers:
        print("Success: data was treated as a stream")
    else:
        print("Failure: data was not treated as a stream")

if __name__ == "__main__":
    test_proxy_iterable()

