import requests
import io
from collections.abc import Iterable

class ProxyFile:
    def __init__(self, file):
        self._file = file

    def __getattr__(self, name):
        return getattr(self._file, name)

def test_proxy_file():
    f = io.BytesIO(b"12345")
    data = ProxyFile(f)

    # Check if it's an Iterable
    print(f"isinstance(data, Iterable): {isinstance(data, Iterable)}")
    print(f"hasattr(data, '__iter__'): {hasattr(data, '__iter__')}")

    req = requests.Request('POST', 'http://httpbin.org/post', data=data)
    prepared = req.prepare()

    print(f"prepared.headers: {prepared.headers}")
    if "Transfer-Encoding" in prepared.headers or "Content-Length" in prepared.headers:
        print("Success: data was treated as a stream")
    else:
        print("Failure: data was not treated as a stream")

if __name__ == "__main__":
    test_proxy_file()

